  calc:{month:'',baselinePeriod:'global',baselineView:'daily',invest:30000,cpl:30,leadMode:'auto',manualLeads:1000,txAg:30,txComp:80,txProp:40,txVenda:30,ticket:100000,actualOverride:null}
