  (st.daily||[]).forEach(r=>{const day=r.date_start||r.date_stop;if(!day)return;if(!meta[day])meta[day]={day,spend:0,impressions:0,clicks:0,lpv:0,leads:0};const x=meta[day];x.spend+=Number(r.spend||0);x.impressions+=Number(r.impressions||0);x.clicks+=Number(r.inline_link_clicks||r.clicks||0);x.lpv+=Number(r.lpv||0);x.leads+=Number(r.leads||0)});
