async function loadHistory3(days=190,force=false){
  if(RC.history&&!force)return RC.history;
  if(RC.historyPromise&&!force)return RC.historyPromise;
  RC.historyPromise=(async()=>{
    // Carrega o período global + a referência histórica (baseline da Calculadora e cartões da Auditoria).
    const G=gp3(),from=new Date();from.setDate(from.getDate()-days+1);const since=G.since<iso(from)?G.since:iso(from),today=iso(new Date()),until=G.until>today?G.until:today;
    try{
      const j=window.RCPeriod?await RCPeriod.fetchJson('/api/history',{since,until},{quiet:true}):await api3(`/api/history?since=${since}&until=${until}`),meta={},crm={};
      (j.metaDaily||[]).forEach(r=>meta[r.day]={...r});
      (j.crmDaily||[]).forEach(r=>crm[r.day]={...r});
      RC.history={meta,crm,since,until,source:j._source||'backend'};return RC.history;
    }catch(e){
      const f=dayMapFromState();RC.history={...f,since,until,source:'cache',error:e.message};return RC.history;
    }
  })();
  try{return await RC.historyPromise}finally{RC.historyPromise=null}
}
