    cpl:'<circle cx="12" cy="12" r="8"/><path d="M12 7v10M15 9.5c-.7-1-1.7-1.5-3-1.5-1.8 0-3 1-3 2.3 0 3.7 6 1.7 6 5 0 1.5-1.3 2.7-3.2 2.7-1.4 0-2.6-.6-3.3-1.7"/>',
