  const filt=r=>RC.auditFilter==='div'?stateOf(r)!=='ok':RC.auditFilter==='meta'?stateOf(r)==='meta':RC.auditFilter==='crm'?stateOf(r)==='crm':true;
  const term=RC.auditSearch.toLowerCase().trim(),shown=rows.filter(r=>filt(r)&&(!term||`${r.name} ${r.email} ${r.phone} ${r.campaign}`.toLowerCase().includes(term)));
